const ACTIONS = ['sendText', 'sendButtons', 'sendList', 'sendTemplate', 'markRead'];
const GATEWAY_ID = /^[A-Za-z0-9]{16}$/;
const PHONE_NUMBER_ID = /^[0-9]+$/;

function isText(value, max) {
  return typeof value === 'string' && value.trim() !== '' && value.length <= max;
}

function validOptions(options, maxCount, maxLabel) {
  if (!Array.isArray(options) || options.length < 1 || options.length > maxCount) {
    return false;
  }
  const ids = new Set();
  for (const option of options) {
    if (!option || !isText(option.id, 200) || !isText(option.label, maxLabel) || ids.has(option.id)) {
      return false;
    }
    ids.add(option.id);
  }
  return true;
}

function validTemplate(template) {
  if (!template || !isText(template.name, 512) || !isText(template.language, 20)) {
    return false;
  }
  const parameters = template.parameters ?? [];
  return Array.isArray(parameters) && parameters.every((value) => typeof value === 'string' || typeof value === 'number');
}

function invalidField(input) {
  if (!ACTIONS.includes(input.action)) return 'action';
  if (!isText(input.clientId, 100)) return 'clientId';
  if (typeof input.gatewayWorkflowId !== 'string' || !GATEWAY_ID.test(input.gatewayWorkflowId)) return 'gatewayWorkflowId';
  if (typeof input.phoneNumberId !== 'string' || !PHONE_NUMBER_ID.test(input.phoneNumberId)) return 'phoneNumberId';
  if (input.action === 'markRead') return isText(input.messageId, 200) ? null : 'messageId';
  if (!isText(input.leadId, 128)) return 'leadId';
  if (input.action === 'sendTemplate') return validTemplate(input.template) ? null : 'template';
  if (!isText(input.text, input.action === 'sendText' ? 4096 : 1024)) return 'text';
  if (input.action === 'sendButtons') return validOptions(input.options, 3, 20) ? null : 'options';
  if (input.action === 'sendList') {
    if (!isText(input.listButton, 20)) return 'listButton';
    return validOptions(input.options, 10, 24) ? null : 'options';
  }
  return null;
}

function messageBody(input) {
  if (input.action === 'markRead') {
    return { messaging_product: 'whatsapp', status: 'read', message_id: input.messageId, typing_indicator: { type: 'text' } };
  }
  const base = { messaging_product: 'whatsapp', recipient_type: 'individual', recipient: input.leadId };
  if (input.action === 'sendText') {
    return { ...base, type: 'text', text: { body: input.text, preview_url: false } };
  }
  if (input.action === 'sendButtons') {
    const buttons = input.options.map((option) => ({ type: 'reply', reply: { id: option.id, title: option.label } }));
    return { ...base, type: 'interactive', interactive: { type: 'button', body: { text: input.text }, action: { buttons } } };
  }
  if (input.action === 'sendList') {
    const rows = input.options.map((option) => ({ id: option.id, title: option.label }));
    return { ...base, type: 'interactive', interactive: { type: 'list', body: { text: input.text }, action: { button: input.listButton, sections: [{ rows }] } } };
  }
  const template = { name: input.template.name, language: { code: input.template.language } };
  const parameters = (input.template.parameters ?? []).map((value) => ({ type: 'text', text: String(value) }));
  if (parameters.length > 0) {
    template.components = [{ type: 'body', parameters }];
  }
  return { ...base, type: 'template', template };
}

function buildRequest(input) {
  const field = invalidField(input);
  if (field !== null) {
    return { valid: false, result: { ok: false, error: { code: 'invalid_input', retryable: false, field } } };
  }
  return {
    valid: true,
    clientId: input.clientId,
    gatewayWorkflowId: input.gatewayWorkflowId,
    method: 'POST',
    path: `/${input.phoneNumberId}/messages`,
    body: messageBody(input),
  };
}

return $input.all().map((item) => ({ json: buildRequest(item.json) }));

const RATE_LIMIT_CODES = [4, 80007, 130429, 131056];
const TRANSIENT_CODES = [1, 2, 131000];

function failure(code, retryable, metaCode = null) {
  return { ok: false, error: { code, retryable, metaCode } };
}

function outcome(response) {
  if (response.error !== undefined) {
    const message = typeof response.error === 'string' ? response.error : String(response.error?.message ?? '');
    return /not active|does not exist|not found|could not find/i.test(message) ? failure('no_gateway', false) : failure('unavailable', true);
  }
  if (response.status === 0) return failure('invalid_request', false);
  if (response.status >= 200 && response.status < 300) {
    const messageId = response.body?.messages?.[0]?.id;
    return messageId ? { ok: true, messageId } : { ok: true };
  }
  const metaCode = response.body?.error?.code ?? null;
  if (response.status === 401 || metaCode === 190) return failure('auth', false, metaCode);
  if (response.status === 429 || RATE_LIMIT_CODES.includes(metaCode)) return failure('rate_limited', true, metaCode);
  if (response.status >= 500 || TRANSIENT_CODES.includes(metaCode)) return failure('unavailable', true, metaCode);
  if (metaCode === 131047) return failure('outside_window', false, metaCode);
  if (metaCode === 131026) return failure('undeliverable', false, metaCode);
  return failure('meta_error', false, metaCode);
}

const firstAttempt = $prevNode.name === 'Call gateway';
return $input.all().map((item, index) => {
  const result = outcome(item.json);
  if (firstAttempt && result.error?.retryable) {
    return { json: { ...$('Build request').itemMatching(index).json, retry: true } };
  }
  return { json: { retry: false, result } };
});
